"use strict";const e=require("../common/vendor.js"),o=require("./user-security.js");exports.guardPayPassword=function(){return o.hasPayPasswordSet()?Promise.resolve({ok:!0}):new Promise((o=>{e.index.showModal({title:"请先设置支付密码",content:"为保障资金安全，支付前需设置 6 位数字支付密码",confirmText:"去设置",cancelText:"取消",success:i=>{i.confirm?(setTimeout((()=>{e.index.navigateTo({url:"/pages/mine/set-password?from=pay",animationType:"slide-in-right",animationDuration:200,fail:()=>{e.index.showToast({title:"打开设密页失败，请从「我的」重试",icon:"none"})}})}),80),o({ok:!1,navigatedToSet:!0})):o({ok:!1,navigatedToSet:!1})},fail:()=>o({ok:!1,navigatedToSet:!1})})}))};
